def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key or not obj:
        return out

    # Rotate the small color diagram clockwise, then scale its cells to
    # the 2x2 repeated blocks making up the large figure.
    r0, r1 = min(r for r,c,v in key), max(r for r,c,v in key)
    c0, c1 = min(c for r,c,v in key), max(c for r,c,v in key)
    kh, kw = r1-r0+1, c1-c0+1
    rotated = {}
    for r,c,v in key:
        rr, cc = c-c0, r1-r
        rotated[(rr,cc)] = v

    # In the demos each key cell maps to one 2-by-2 block, while the
    # whole pattern is aligned with the upper-left of the 8 figure.
    or0, oc0 = min(r for r,c in obj), min(c for r,c in obj)
    for (rr,cc),v in rotated.items():
        for dr in range(2):
            for dc in range(2):
                r, c = or0 + 2*rr + dr, oc0 + 2*cc + dc
                if 0 <= r < h and 0 <= c < w and grid[r][c] == 8:
                    out[r][c] = v
    return out
